-- Payer reprocessing (repricing) by payer: claim_corrections rows with a replacement_adjudication_record_id (reason payer_updated_network_pricing_and_reprocessed_same_service). For each, allowed change = replacement adjudication allowed_cents - original adjudication allowed_cents. Payer = source_system of the replacement medical_claims adjudication. Columns: payer, reprocessed_claims (distinct claim_ids), net_allowed_change (dollars, 2 decimals).
WITH r AS MATERIALIZED (SELECT patient, stream, payload FROM records WHERE stream IN ('medical_claims','claim_corrections')),
adj AS MATERIALIZED (SELECT json_extract(payload,'$.record_id') rid, json_extract(payload,'$.allowed_cents') allowed, json_extract(payload,'$.source_system') payer FROM r WHERE stream='medical_claims'),
cc AS MATERIALIZED (SELECT json_extract(payload,'$.claim_id') cid, json_extract(payload,'$.original_adjudication_record_id') o, json_extract(payload,'$.replacement_adjudication_record_id') n FROM r WHERE stream='claim_corrections' AND json_extract(payload,'$.replacement_adjudication_record_id') IS NOT NULL)
SELECT nw.payer AS payer, COUNT(DISTINCT cc.cid) AS reprocessed_claims, ROUND(SUM(nw.allowed-og.allowed)/100.0,2) AS net_allowed_change FROM cc JOIN adj og ON og.rid=cc.o JOIN adj nw ON nw.rid=cc.n GROUP BY nw.payer ORDER BY nw.payer;
